form.script:
$(document).ready(function(){
    if(window.innerWidth < 1000){
        $('.total_revenue_td').addClass('d-none')
    }
    $('.cash_flow_page').click(function(){
        setTimeout(function(){
            setWidthTotals()
        })
    })
    function setWidthTotals(){
        $('[name="cash_flow_lines"] table thead th').each(function(index, td){
            $($('.cash_flow_totals tbody tr:first td')[index]).css('width',$(td).css('width'))
            $($('.cash_flow_totals tbody tr:first td')[index]).css('min-width',$(td).css('width'))
            $($('.cash_flow_totals tbody tr:first td')[index]).css('max-width',$(td).css('width'))
        })
    };
    $('[name="profit_loss_lines"] .table-responsive').on('scroll', function() {
        const remainingScroll = $(this)[0].scrollWidth - $(this).outerWidth() - $(this).scrollLeft();
        const threshold = 25;
        if (remainingScroll <= threshold) {
            $('.total_revenue_td').removeClass('d-none');
            $('.total_revenue_div').css('margin', '-63px 1px 1px 1px');
        }
        else{
            $('.total_revenue_td').addClass('d-none')
        }
    });
    $('[name="cash_flow_lines"] .table-responsive').on('scroll', function() {
        $('.cash_flow_totals').scrollLeft($(this).scrollLeft());
        $('.cash_flow_signing_block .table-responsive').scrollLeft($(this).scrollLeft());
    });
    $('.cash_flow_totals').on('scroll', function() {
        $('[name="cash_flow_lines"] .table-responsive').scrollLeft($(this).scrollLeft());
        $('.cash_flow_signing_block .table-responsive').scrollLeft($(this).scrollLeft());
    });
    $('.cash_flow_signing_block .table-responsive').on('scroll', function() {
        $('[name="cash_flow_lines"] .table-responsive').scrollLeft($(this).scrollLeft());
        $('.cash_flow_totals').scrollLeft($(this).scrollLeft());
    });
    change_cost_sheet_header()
    $('input.cost_sheet_header').change(function(){
        change_cost_sheet_header()
    })
})
function change_cost_sheet_header(){
    var values = $('.cost_sheet_header').text().split('~');
    $('.cost_sheet_lines thead tr th').each(function(i, obj){
        if(i > 0){
            $(this).empty()
            $(this).append(values[i - 1])
        }
    })
}
$("input.o_field_number ").on("click", function() {
    $(this).select();
});
$("input.o_field_number ").on("change", function() {
    var value = $(this).val()
    if(value != '' && String(parseFloat(value)) != 'NaN'){
        $(this).val(parseFloat(value));
    }
});
